mapper.select:
SELECT 
FROM posts p JOIN users u ON u.id = p.user_id
WHERE p.id = #{id}

SELECT 
FROM posts p JOIN users u ON u.id = p.user_id

	p.id < #{cursor}

ORDER BY p.id DESC
LIMIT #{limit}

SELECT 
FROM posts p JOIN users u ON u.id = p.user_id
WHERE p.user_id = #{userId}
AND p.id < #{cursor}
ORDER BY p.id DESC
LIMIT #{limit}

SELECT 
FROM posts p JOIN users u ON u.id = p.user_id
WHERE p.user_id IN (
	SELECT followee_id FROM follows WHERE follower_id = #{viewer}
	UNION ALL
	SELECT CAST(#{viewer} AS uuid)
)
AND p.id < #{cursor}
ORDER BY p.id DESC
LIMIT #{limit}

SELECT id, post_id, object_key, position FROM post_images WHERE post_id IN
#{postId}
ORDER BY post_id, position
